import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  metadataBase: new URL("https://bloodpoint.pages.dev"),

  title: "Blood Point | Blood Donation Platform",

  description:
    "Blood Point is a blood donation platform that helps connect blood donors with people in need. Discover donors and support life-saving blood donation through a user-friendly web experience.",

  openGraph: {
    type: "website",
    url: "https://bloodpoint.pages.dev/",
    siteName: "Blood Point",
    title: "Blood Point | Blood Donation Platform",
    description:
      "Connect blood donors with people in need through Blood Point. Explore a user-friendly platform designed to support blood donation and help save lives.",
    images: [
      {
        url: "/blood-point-preview.png",
        width: 1200,
        height: 630,
        alt: "Blood Point - Blood Donation Platform",
      },
    ],
  },

  twitter: {
    card: "summary_large_image",
    title: "Blood Point | Blood Donation Platform",
    description:
      "Discover blood donors and help connect people in need through the Blood Point donation platform.",
    images: ["/blood-point-preview.png"],
  },
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html
      lang="en"
      className={`${geistSans.variable} ${geistMono.variable} h-full antialiased`}
    >
      <body className="min-h-full flex flex-col">{children}</body>
    </html>
  );
}

